import json,time,urllib.request,urllib.error,email.utils
from datetime import datetime,timezone
from decimal import Decimal,ROUND_HALF_UP
from collections import Counter
BASE='http://localhost:8080'
token=None
stats=Counter()
def request(path,method='GET',auth=True):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token','POST',False)['token']
  headers={'Authorization':'Bearer '+token} if auth else {}
  try:
   with urllib.request.urlopen(urllib.request.Request(BASE+path,headers=headers,method=method),timeout=30) as r:
    return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode(); stats[str(e.code)]+=1
   print('Retry',path,e.code,body,dict(e.headers),flush=True)
   if e.code==401 and auth:
    token=[REDACTED_SECRET]
   if e.code==429:
    delay=e.headers.get('Retry-After')
    if delay:
     try: wait=float(delay)
     except ValueError: wait=max(0,(email.utils.parsedate_to_datetime(delay)-datetime.now(timezone.utc)).total_seconds())
    else:
     data=json.loads(body);wait=float(data.get('retry_after',data.get('retry_after_seconds',1)))
    time.sleep(wait);continue
   if e.code>=500 or e.code in (408,403):
    time.sleep(1);continue
   raise
  except (urllib.error.URLError,TimeoutError,ConnectionError):
   stats['network']+=1;time.sleep(1)
orders={};duplicates=0;pages=[];path='/orders?page=1';total_pages=None
while path:
 data=request(path)
 assert data['page']==len(pages)+1
 if total_pages is None: total_pages=data['total_pages']
 assert total_pages==data['total_pages']
 pages.append(data)
 for o in data['items']:
  if o['id'] in orders:
   duplicates+=1
   assert orders[o['id']]==o, 'Conflicting duplicate'
  else:orders[o['id']]=o
 path=data['next']
 print('Page',data['page'],'of',total_pages,'unique',len(orders),flush=True)
assert len(pages)==total_pages
start=datetime(2025,3,1,tzinfo=timezone.utc);end=datetime(2025,6,1,tzinfo=timezone.utc)
def utc(o):return datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
qualified=[o for o in orders.values() if o['status']=='shipped' and start<=utc(o)<end]
customers={}
for cid in sorted({o['customer_id'] for o in qualified}):
 c=request('/customers/'+cid);assert c['id']==cid;customers[cid]=c
 print('Customers',len(customers),flush=True)
regions=dict.fromkeys(['north','south','east','west'],0)
for o in qualified:
 c=customers[o['customer_id']];assert type(c['discount_pct']) is int
 n=o['amount_cents']*(100-c['discount_pct'])
 discounted=int((Decimal(n)/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
 assert discounted==(n+50)//100
 regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qualified),'duplicates_skipped':duplicates,'by_region':regions}
# Independently recompute via Decimal from all distinct orders.
check=sum(int((Decimal(o['amount_cents'])*(1-Decimal(customers[o['customer_id']]['discount_pct'])/100)).quantize(Decimal('1'),rounding=ROUND_HALF_UP)) for o in orders.values() if o['status']=='shipped' and start<=utc(o)<end)
assert check==result['total_cents']
assert len({o['id'] for o in qualified})==len(qualified)
with open('/tmp/reconciliation-audit.json','w') as f:json.dump({'pages':pages,'customers':customers,'stats':dict(stats)},f)
with open('/workspace/result.json','w') as f:json.dump(result,f,indent=2);f.write('\\n')
with open('/workspace/result.json') as f:written=json.load(f)
assert set(written)=={'total_cents','order_count','duplicates_skipped','by_region'}
assert set(written['by_region'])=={'north','south','east','west'}
assert all(type(v) is int for v in written['by_region'].values())
assert sum(written['by_region'].values())==written['total_cents']
print('RESULT',json.dumps(result),flush=True)
print('UTC boundary differences',json.dumps([o for o in orders.values() if o['status']=='shipped' and (start<=utc(o)<end)"'!=('"'2025-03-01'<=o['placed_at'][:10]<='2025-05-31')]),flush=True)
